@startuml

class PlayerProfile {
  + targetPositions : string[]
}

class PlayerAttribute {
  + name : string
  + value : float
}

class Player {
  + name : string
}

class ScoutingAssignment {
  + status : string
}

class ScoutingReport {
  + pros : string
  + cons : string
  + recommendation : string
}

class LongList {
  + evaluationDate : date
}

class ShortList {}

class OfficialOffer {}

class Employee {}

class HeadCoach extends Employee {}

class Director extends Employee {}

class Scout extends Employee {}

class HeadScout extends Scout {}

PlayerProfile "1" *-- "* PlayerAttribute" PlayerAttribute
PlayerProfile "1" -- "*" Player
Player "1" -- "0..1" LongList
Player "0..1" -- "0..1" ShortList
Player "0..1" -- "0..1" OfficialOffer

Scout "1" -- "*" ScoutingAssignment : carries out
Scout "1" -- "*" ScoutingReport : submits
ScoutingAssignment "1" *-- "1" ScoutingReport : results in
ScoutingAssignment "0..*" -- "1" Player : investigates
ScoutingAssignment "0..*" -- "1" Scout : assigned to

HeadCoach "1" -- "*" PlayerProfile : identifies
HeadScout "1" -- "*" ScoutingAssignment : sets up
HeadScout "1" -- "1" Director : decides with

Director "1" -- "*" OfficialOffer : makes

@enduml

